{"content": "// CSV exporter.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

function csvField(value: string): string {
  if (/[,"\r\n]/.test(value)) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error('Permission denied: export requires admin role');
  }

  const tasks = Array.from((taskManager as { getTask: (id: string) => unknown } & Record<string, unknown> & {
    tasks: Map<string, { id: string; title: string; status: string; assignee: string; createdAt: number }>;
  }).tasks.values());

  const header = 'id,title,status,assignee,createdAt';
  const rows = tasks.map((t) =>
    [csvField(t.id), csvField(t.title), csvField(t.status), csvField(t.assignee), String(t.createdAt)].join(',')
  );

  record({ action: 'export', userId, timestamp: Date.now() });

  return [header, ...rows].join('\n');
}
", "path": "src/exporter.ts"}

